import { useMemo, useState } from 'react';
import { FlatList, Linking, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { router } from 'expo-router';
import { ChevronRight, ExternalLink, Search, X } from 'lucide-react-native';

import { Colors, FontFamily, FontSize, MaxWidth, Radius, Spacing } from '@/constants/design';
import { Header } from '@/components/ui/Header';
import { useTheme } from '@/context/ThemeContext';
import type { ThemeTokens } from '@/constants/theme-tokens';
import data from '@/data/openSourceLicenses.json';

// Generated by `node scripts/generate-licenses.js` from the installed production
// dependency tree. Regenerate after any dependency change.
interface Pkg {
  name: string;
  version: string;
  license: string;
  repository: string | null;
  copyright: string | null;
  textId: string | null;
}
const PACKAGES = data.packages as Pkg[];
const TEXTS = data.texts as Record<string, string>;

export default function LicensesScreen() {
  const { theme } = useTheme();
  const styles = useStyles(theme);
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<Pkg | null>(null);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return PACKAGES;
    return PACKAGES.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q));
  }, [query]);

  const goBack = () => {
    if (selected) { setSelected(null); return; }
    if (router.canGoBack()) router.back(); else router.replace('/settings-help' as any);
  };

  if (selected) {
    const text = selected.textId ? TEXTS[selected.textId] : '';
    return (
      <View style={styles.screen}>
        <Header variant="inner" title="License" onBack={goBack} />
        <FlatList
          data={[0]}
          keyExtractor={() => 'detail'}
          contentContainerStyle={styles.content}
          renderItem={() => (
            <View style={{ maxWidth: MaxWidth, width: '100%', alignSelf: 'center', gap: 10 }}>
              <Text testID="license-name" style={styles.detailName}>{selected.name}</Text>
              <Text style={styles.meta}>Version {selected.version} · {selected.license}</Text>
              {selected.copyright && <Text style={styles.meta}>{selected.copyright}</Text>}
              {selected.repository && (
                <TouchableOpacity
                  style={styles.link}
                  onPress={() => Linking.openURL(selected.repository!).catch(() => {})}
                  accessibilityRole="link">
                  <ExternalLink color={theme.cyanOnLight} size={16} strokeWidth={1.75} />
                  <Text style={styles.linkText} numberOfLines={1}>{selected.repository}</Text>
                </TouchableOpacity>
              )}
              <Text testID="license-text" style={styles.licenseText} selectable>
                {text || `This package is distributed under the ${selected.license} license. The license file was not included in the installed package; see the repository above for the full text.`}
              </Text>
            </View>
          )}
        />
      </View>
    );
  }

  return (
    <View style={styles.screen}>
      <Header variant="inner" title="Open Source Licenses" onBack={goBack} />
      <View style={styles.searchWrap}>
        <View style={styles.searchRow}>
          <Search color={theme.textMuted} size={18} strokeWidth={1.75} />
          <TextInput
            testID="license-search"
            style={styles.searchInput}
            value={query}
            onChangeText={setQuery}
            placeholder="Search packages or licenses"
            placeholderTextColor={theme.textMuted}
            autoCapitalize="none"
            autoCorrect={false}
            accessibilityLabel="Search packages"
          />
          {query.length > 0 && (
            <TouchableOpacity onPress={() => setQuery('')} accessibilityLabel="Clear search"
              hitSlop={{ top: 10, bottom: 10, left: 10, right: 10 }}>
              <X color={theme.textMuted} size={18} strokeWidth={1.75} />
            </TouchableOpacity>
          )}
        </View>
        <Text style={styles.summary}>
          {filtered.length} of {data.packageCount} third-party packages. TenisX is built with open-source
          software; each license applies to its package.
        </Text>
      </View>
      <FlatList
        data={filtered}
        keyExtractor={(p) => `${p.name}@${p.version}`}
        contentContainerStyle={styles.listContent}
        initialNumToRender={20}
        windowSize={8}
        keyboardShouldPersistTaps="handled"
        renderItem={({ item }) => (
          <TouchableOpacity
            testID="license-row"
            style={styles.row}
            onPress={() => setSelected(item)}
            accessibilityRole="button">
            <View style={{ flex: 1 }}>
              <Text style={styles.name} numberOfLines={1}>{item.name}</Text>
              <Text style={styles.meta}>{item.version} · {item.license}</Text>
            </View>
            <ChevronRight color={theme.textMuted} size={18} strokeWidth={1.75} />
          </TouchableOpacity>
        )}
        ListEmptyComponent={<Text style={[styles.meta, { padding: 24, textAlign: 'center' }]}>No matching packages.</Text>}
      />
    </View>
  );
}

function useStyles(theme: ThemeTokens) {
  return useMemo(() => StyleSheet.create({
  screen: { flex: 1, backgroundColor: theme.pageBg },
  content: { padding: Spacing.pagePx, paddingBottom: 60 },
  listContent: { paddingHorizontal: Spacing.pagePx, paddingBottom: 60 },
  searchWrap: { paddingHorizontal: Spacing.pagePx, paddingTop: 16, paddingBottom: 8, gap: 10 },
  searchRow: {
    flexDirection: 'row', alignItems: 'center', gap: 10, minHeight: 48, paddingHorizontal: 14,
    borderRadius: Radius.input, borderWidth: 1, borderColor: theme.border, backgroundColor: theme.cardBg,
  },
  searchInput: { flex: 1, minHeight: 48, fontFamily: FontFamily.manropeMedium, fontSize: FontSize.body, color: theme.textPrimary },
  summary: { fontFamily: FontFamily.manropeMedium, fontSize: FontSize.label, lineHeight: 20, color: theme.textMuted },
  row: {
    flexDirection: 'row', alignItems: 'center', gap: 12, minHeight: 56, paddingVertical: 10,
    borderBottomWidth: 1, borderBottomColor: theme.border,
  },
  name: { fontFamily: FontFamily.manropeSemiBold, fontSize: FontSize.body, color: theme.textPrimary },
  meta: { fontFamily: FontFamily.manropeMedium, fontSize: FontSize.label, color: theme.textMuted, lineHeight: 20 },
  detailName: { fontFamily: FontFamily.spaceGroteskBold, fontSize: FontSize.sectionTitle, color: theme.textPrimary },
  link: { flexDirection: 'row', alignItems: 'center', gap: 8, minHeight: 44 },
  linkText: { flex: 1, fontFamily: FontFamily.manropeMedium, fontSize: FontSize.label, color: theme.cyanOnLight },
  licenseText: {
    fontFamily: FontFamily.manropeMedium, fontSize: FontSize.label, lineHeight: 20, color: theme.textSecondary, marginTop: 8,
  },
}), [theme]);
}
